# Display only: not executable, not round-trippable; toke semantics apply.
# Key: T!E -> Result[T, E]; x!E -> propagate(x, E); '# mut' marks a mutable
# binding; _fnN/_ifN/_mtN are a closure, if or mt lifted out of an expression;
# fixed-width types other than i64/f64 keep their toke names (i32, u8, f32).

# module mortgage.calc
import mortgage.model as md
import std.math as math


def validate(s: scenario) -> Result[scenario, calcerr]:
    if s.rate < 0.0 or s.rate > 1.0:
        return calcerr.invalidrate(s.rate)
    if s.term < 1:
        return calcerr.invalidterm(s.term)
    return s


def monthly(s: scenario) -> float:
    n = s.term * 12
    r = s.rate / 12.0
    if r < 0.000000001:
        return s.principal / float(n)
    rn = math.pow(1.0 + r, float(n))
    return s.principal * (r * rn) / (rn - 1.0)


def amortise(s: scenario) -> list[payment]:
    pmt = monthly(s)
    n = s.term * 12
    bal = s.principal  # mut
    sched = []  # mut
    i = 1
    while i < int(n) + 1:
        mi = bal * (s.rate / 12.0)
        mp = pmt + s.extra  # mut
        if mp > bal + mi:
            mp = bal + mi
        princ = mp - mi
        bal = bal - princ
        if bal < 0.0:
            bal = 0.0
        row = payment(month=u64(i), payment=mp, principal=princ, interest=mi, balance=bal)
        sched = sched.push(row)
        if bal < 0.01:
            return sched
        i = i + 1
    return sched


def calculate(s: scenario) -> Result[result, calcerr]:
    ok = propagate(validate(s), calcerr)
    pmt = monthly(s)
    sched = amortise(s)
    n = sched.len
    totalcost = 0.0  # mut
    totalinterest = 0.0  # mut
    i = 0
    while i < int(n):
        row = sched[i]
        totalcost = totalcost + row.payment
        totalinterest = totalinterest + row.interest
        i = i + 1
    return result(monthly=pmt, totalinterest=totalinterest, totalcost=totalcost, schedule=sched)
